import RequestError from "#helpers/requestError";
import Service from "#class/service";
import type { Opgave, OpgaveId, OpgaveRij, OpgaveWaarden, Polisdata, PolisId, PostResponse, RowRes } from "#types";
import assert from "assert";

/**
 * Axongetrouwe module
 * @method opgaven Retourneert alle opgaven van een gegeven polis
 * @method markeerNietNodig Markeert een opgave als niet nodig
 * @method getStatusText Haalt de getoonde status op van een opgave
 * @method invoerenOpgaveWaarden Voer omzet en jaarloon in bij opgave
 */
export default class OpgavenService extends Service {

    /** Retourneert alle opgaven van de polis */
    vind(polisnummer: PolisId) {
        return this.session.getAxon<RowRes<OpgaveRij>>(`policies/${polisnummer}/declarations`).then(r => r.rows);
    }

    /** Retourneert een specifieke opgave van een polis */
    vindDetails(polisnummer: PolisId, id: OpgaveId) {
        return this.session.getAxon<Opgave>(`policies/${polisnummer}/declarations/${id}`);
    }

    /**
    * Annuleert de opgave door deze als 'niet nodig' te markeren in Axon.
    * Vereist dat de status 'wachtend' is;
    * bij elke andere status wordt de actie geweigerd.
    */
    async markeerNietNodig(opgave: OpgaveRij, polisData: Polisdata) {
        if (opgave.isComplete || opgave.isMarkedNotNeeded || opgave.isCancelled)
            return false;

        const url = `policies/${polisData.externalIdentifier satisfies PolisId}/declarations/${opgave.policyDeclarationExtId}/marking-not-needed`;
        return this.session.putAxon<PostResponse>(url, polisData.tsChanged, polisData);
    }

    getStatusText(opgave: OpgaveRij) {
        const { isMarkedNotNeeded, isCancelled, isCancelProcessed, isProcessed, isComplete } = opgave;
        if (isMarkedNotNeeded && !isCancelled) return 'niet nodig' as const;
        if (isCancelled ? isCancelProcessed || !isProcessed : isProcessed) return 'verwerkt' as const;
        if (isCancelled || isComplete) return 'nog te verwerken' as const;
        return 'wachtend' as const;
    }

    /**
     * Voert opgavewaarden in bij de aangegeven opgave.
     * 
     * @param opgave De opgave die bewerkt moet worden
     * @param polisnummer De polis waartoe de opgave behoort
     * @param omzet De omzet (kan `null` worden gelaten als Axon hier niet om vraagt)
     * @param jaarloon Het jaarloon (kan `null` worden gelaten als Axon hier niet om vraagt)
     * @throws Wanneer omzet of jaarloon `null` is en Axon hier wel om vraagt.
     * @returns
     */
    async invoerenOpgaveWaarden(opgave: Opgave, polisnummer: PolisId, waarden: OpgaveWaarden): Promise<PostResponse> {
        // YYYY-MM-DD
        const declarationTypeList = await this.session.getAxon<any[]>(
            `policies/${polisnummer}/declaration-fields`,
            {
                dateDeclarationStart: opgave.datePeriodStart,
                dateDeclarationEnd: opgave.datePeriodEnd,
                policyDeclarationExitId: opgave.externalIdentifier,
            }
        );
        const { length } = declarationTypeList
        assert(length > 0, "Had meerdere invoervelden verdacht, kreeg 0");

        declarationTypeList.forEach(d => {
            assert(d.declarationFieldList.length === 1);

            const type = d.declarationTypeExtId
            const editvalue = d.declarationFieldList[0].declarationEditValue;

            let category: "amountValue" | "integerNumberValue" | "listValue" | "decimalNumberValue" | null = null;

            const setValue = (naam: keyof OpgaveWaarden) => {
                assert(typeof waarden[naam] === "number", `Geen ${naam} opgegeven, wel nodig voor deze specifieke opgave`);
                assert(category, "Fout in Axon-Controller: geen categorie toegewezen.")
                editvalue[category] = waarden[naam];
            }

            switch (type) {
                case "opgOmzet":
                    category = "amountValue";
                    setValue("omzet");
                    break;
                case "opgJaarloon":
                    category = "amountValue";
                    setValue("jaarloon");
                    break;
                case "opgHerbouwwaarde":
                    category = "amountValue";
                    setValue("herbouwwaarde");
                    break;
                case "opgPraktijkbeoefenaars":
                    category = "integerNumberValue"
                    setValue("praktijkbeoefenaars");
                    break;
                case "opgPaarden":
                    category = "integerNumberValue";
                    setValue("paarden");
                    break;
                case "opgStallingsplaatsen":
                    category = "integerNumberValue";
                    setValue("stallingsplaatsen");
                    break;
                default:
                    throw new Error(`Onverwacht veld gevonden: ${type}`);
            };
        });

        const data = {
            ...opgave,
            declarationTypeList,
        }

        try {
            return await this.session.putAxon<PostResponse<any>>(
                `policies/${polisnummer}/declarations/${opgave.externalIdentifier}/enter-declaration-values`,
                opgave.changeToken,
                data,
            )
        } catch (err) {
            if (err instanceof RequestError && err.status === 400)
                throw new Error(`Er is iets fout gegaan met statuscode 400, dus misschien is het niet mogelijk om opgavewaarden in te voeren voor deze opgave.`);
            else throw err;
        }
    }

    async invoerenOpgaveWaardenExt(opgave: Opgave, polisnummer: PolisId, velden: OpgaveVeld[]): Promise<PostResponse> {
        // YYYY-MM-DD
        const declarationTypeList = await this.session.getAxon<any[]>(
            `policies/${polisnummer}/declaration-fields`,
            {
                dateDeclarationStart: opgave.datePeriodStart,
                dateDeclarationEnd: opgave.datePeriodEnd,
                policyDeclarationExitId: opgave.externalIdentifier,
            }
        );
        assert(declarationTypeList.length > 0, "Had meerdere invoervelden verwacht, kreeg 0");

        const nogTeGebruiken = new Map(velden.map(v => [v.id, v]));

        declarationTypeList.forEach(d => {
            assert(d.declarationFieldList.length === 1, `Verwachtte precies 1 invoerveld voor ${d.declarationTypeExtId}`);

            const type: string = d.declarationTypeExtId;
            const veld = nogTeGebruiken.get(type);
            assert(veld, `Geen waarde opgegeven voor "${type}", wel nodig voor deze specifieke opgave`);

            d.declarationFieldList[0].declarationEditValue[veld.category] = veld.value;
            nogTeGebruiken.delete(type);
        });

        assert(
            nogTeGebruiken.size === 0,
            `Waarden opgegeven voor velden die deze opgave niet kent: ${[...nogTeGebruiken.keys()].join(", ")}`
        );

        const data = { ...opgave, declarationTypeList };

        try {
            return await this.session.putAxon<PostResponse<any>>(
                `policies/${polisnummer}/declarations/${opgave.externalIdentifier}/enter-declaration-values`,
                opgave.changeToken,
                data,
            );
        } catch (err) {
            if (err instanceof RequestError && err.status === 400)
                throw new Error(`Er is iets fout gegaan met statuscode 400, dus misschien is het niet mogelijk om opgavewaarden in te voeren voor deze opgave.`);
            else throw err;
        }
    }
}

type OpgaveCategorie = "amountValue" | "integerNumberValue" | "listValue" | "decimalNumberValue";

interface OpgaveVeld {
    /** declarationTypeExtId, bv. "opgOmzet" */
    id: string;
    category: OpgaveCategorie;
    value: number | string;
}
